    BEGIN;

    INSERT INTO genres (id, name_en, name_th) VALUES
        (28, 'Action', 'บู๊'),
        (12, 'Adventure', 'ผจญ'),
        (16, 'Animation', 'แอนนิเมชั่น'),
        (35, 'Comedy', 'ตลก'),
        (80, 'Crime', 'อาชญากรรม'),
        (99, 'Documentary', 'สารคดี'),
        (18, 'Drama', 'หนังชีวิต'),
        (10751, 'Family', 'ครอบครัว'),
        (27, 'Horror', 'สยองขวัญ'),
        (10402, 'Music', 'ดนตรี'),
        (9648, 'Mystery', 'ลึกลับ'),
        (10749, 'Romance', 'หนังรักโรแมนติก'),
        (878, 'Science Fiction', 'นิยายวิทยาศาสตร์'),
        (53, 'Thriller', 'ระทึกขวัญ')
    ON CONFLICT (id) DO UPDATE SET
        name_en = EXCLUDED.name_en,
        name_th = COALESCE(EXCLUDED.name_th, genres.name_th);

    INSERT INTO movies (id, title, title_th, original_title, original_language, overview, overview_th,
                        release_date, vote_average, poster_path, popularity) VALUES
        (1423191, 'Resident Evil', 'เรสซิเดนท์ อีวิล', 'Resident Evil', 'en', NULL, 'เรื่องราวของคนส่งของผู้โชคร้ายคนหนึ่ง ที่กำลังนำส่งพัสดุไปยังโรงพยาบาลอันห่างไกล ไม่นานนักเขาก็ได้พบว่า ตัวเองตกอยู่ท่ามกลางการแพร่ระบาด และต้องต่อสู้ฝ่าฟันฝูงสิ่งมีชีวิตกลายพันธุ์เพื่อเอาตัวรอด', '2026-01-01', 7.30, 'https://image.tmdb.org/t/p/w342/i7UyjfPio0VFHB9rBUZSFyhOoM8.jpg', 1000.0000),
        (1288445, 'Mutiny', 'คนระห่ำห้ามรอด', 'Mutiny', 'en', NULL, 'หลังจากเจ้านายผู้เป็นเจ้าของอุตสาหกรรมพันล้านถูกฆาตกรรมต่อหน้าเขา โคล รีด ก็ได้ถูกวางตัวเอาไว้ให้เป็นแพะรับบาป ทำให้เขาต้องพยายามหลบหนีไปพร้อมกับเปิดโปงแผนการสมคบคิดระดับนานาชาติ', '2026-01-01', 7.30, 'https://image.tmdb.org/t/p/w342/pu2VxGlpGwffOx292w18b1tv96j.jpg', 999.0000),
        (1263337, 'Heart of the Beast', 'หัวใจผจญไพร', 'Heart of the Beast', 'en', NULL, 'หลังจากเหตุเครื่องบินตกอันน่าสะพรึงกลัว เจมส์ เบลมอนต์ เจ้าหน้าที่หน่วยรบพิเศษ และ โอดิน สุนัขคู่ใจผู้ร่วมรบ ต้องติดอยู่ท่ามกลางถิ่นทุรกันดารอันเวิ้งว้างของอะแลสกา ทั้งสองจำเป็นต้องต่อสู้เพื่อเอาชีวิตรอดอย่างโหดร้ายท่ามกลางสภาพแวดล้อมอันโหดเหี้ยม', '2026-01-01', 7.70, 'https://image.tmdb.org/t/p/w342/1ApfSA8JTqeha3GTFEY8syV4auq.jpg', 998.0000),
        (299534, 'Avengers: Endgame', 'อเวนเจอร์ส: เผด็จศึก', 'Avengers: Endgame', 'en', NULL, 'เรื่องราวการปิดจักรวาลมาร์เวลเฟส 3 เหตุการณ์ภายหลังจากที่ธานอสดีดนิ้วล้างครึ่งจักรวาล เหล่าฮีโร่ที่เหลือรอดจะหาทางกอบกู้จักรวาลนี้คืนมาได้อย่างไร โดยในภาคนี้จะมีตัวเด็ดอย่างกัปตันมาร์เวลมาร่วมเสริมทัพด้วย', '2019-01-01', 8.20, 'https://image.tmdb.org/t/p/w342/ulzhLuWrPK07P1YkdWQLZnQh1JL.jpg', 997.0000),
        (1422011, 'It Ends', 'สิ้น. สุด.', 'It Ends', 'en', NULL, 'จากทริปขับรถธรรมดา กลายเป็นฝันร้ายที่ไม่มีวันสิ้นสุด เมื่อเพื่อน 4 คนหลงเข้าสู่ถนนลึกลับที่ทอดยาวอย่างไร้จุดหมาย พร้อมบางสิ่งที่รออยู่ในความมืด', '2026-01-01', 5.60, 'https://image.tmdb.org/t/p/w342/6dfAGvZWbJnzWfSZ8gxFj63BNAH.jpg', 996.0000),
        (1101412, 'Fall 2: Deadpoint', 'แส่! ท้านรก', 'Fall 2: Deadpoint', 'en', NULL, 'ในขณะที่กำลังไว้ทุกข์ให้กับการจากไปของ ชิโลห์ น้องสาวของเธอ แจ็คซ์ ฮันเตอร์ ก็ได้สนิทสนมกับ ลูเช เพื่อนผู้กล้าหาญของ ชิโลห์ พวกเธอได้เดินทางไปเผชิญความท้าทายบนทางเดินริมหน้าผาสุดอันตรายของเขาขวัญในประเทศไทย ที่ซึ่งเหตุการณ์หินถล่มทำให้ทั้งสองติดอยู่บนทางเดินที่ความสูงกว่า 3,000 ฟุต ทำให้ แจ็คซ์ ต้องเผชิญกับความกลัวของเธอเพื่อเอาชีวิตรอด', '2026-01-01', 6.20, 'https://image.tmdb.org/t/p/w342/fgSm5ylwiXbIHn8UbUXDjk9RRu4.jpg', 995.0000),
        (1291595, 'Insidious: Out of the Further', 'วิญญาณตามติด หลุดจากนรก', 'Insidious: Out of the Further', 'en', NULL, 'เจ็มม่า คุณแม่วัยสาว กำลังเลี้ยงดูแล้วสาวของเธอในบ้านหลังเดียวกันกับที่เธอเติบโตขึ้นมา โดยต่อมาเธอพบว่า ตัวเธอเองสามารถเดินทางไปใน เดอะ เฟอร์เธอร์ ได้ พร้อมกับความสามารถในการนำเอาสิ่งอาศัยอยู่ในที่แห่งนั้น กลับมายังโลกแห่งความเป็นจริง', '2026-01-01', 6.50, 'https://image.tmdb.org/t/p/w342/4tTrW9dXCByS5wt2pXVWb58zNjz.jpg', 994.0000),
        (1302904, 'Practical Magic 2', 'สองสาวพลังรัก เมจิกมนตราเสน่หา', 'Practical Magic 2', 'en', NULL, 'ครอบครัวแม่มดหลากหลายรุ่น ที่ถูกสาปไม่ได้พบเจอกับความรักยาวนานหลายศตวรรษ ได้พยายามที่จะทำลายคำสาปด้วยการเผชิญหน้ากับความลับอันดำมืดและการเสียสละซึ่งกันและกัน', '2026-01-01', 6.20, 'https://image.tmdb.org/t/p/w342/ogwQOLbCfncjvBhFb5l0OmQH8KC.jpg', 993.0000),
        (1384216, 'The Dog Stars', 'เดอะ ด็อก สตารส์', 'The Dog Stars', 'en', NULL, 'ในโลกหลังการล่มสลายที่ไวรัสได้ทำลายล้างมนุษยชาติ เหล่าผู้รอดชีวิตต้องเผชิญหน้ากับสิ่งมีชีวิตที่เรียกว่า รีปเปอร์ ในขณะที่ ฮิก นักบินคนหนึ่งที่รอดจากโรคระบาดดังกล่าว แต่ได้สูญเสียภรรยาของเขาไป ต้องเดินทางตามหาที่มาของเสียงลึกลับพร้อมกับสุนัขของเขา', '2026-01-01', 6.60, 'https://image.tmdb.org/t/p/w342/A7i16oDi03qrKep5pBfuTWNUTb.jpg', 992.0000),
        (1058424, 'Hope', 'โฮป', 'Hope', 'en', NULL, 'เมื่อก่อนการเกิดการค้นพบลึกลับขึ้นที่แถบชานเมืองของเมืองท่าอันห่างไกลแห่งหนึ่ง ผู้อยู่อาศัยในเมืองแห่งนี้ต้องพบว่าพวกเขาต้องต่อสู้หลังชนกำแพงเพื่อเอาชีวิตรอดจากอะไรบางอย่างที่พวกเขาไม่เคยเผชิญมาก่อน', '2026-01-01', 7.20, 'https://image.tmdb.org/t/p/w342/1n37BJchWHLiSYQkuFxe5KjB951.jpg', 991.0000),
        (843352, 'Legend of the White Dragon', 'ไวท์ดรากอน', 'Legend of the White Dragon', 'en', NULL, 'หลังจากการศึกครั้งใหญ่อันแสนสูญเสียเมื่อ 3 ปีก่อน เมืองถูกทำลายและเหล่าฮีโร่กลับตกเป็นจำเลยสังคม โดนยึดฉายาและถูกไล่ล่า Erik Reed (รับบทโดย Jason David Frank) ฮีโร่ผู้เคยดำรงตำแหน่ง The White Dragon ต้องหลบซ่อนตัวในฐานะผู้ลี้ภัย แต่แล้วเขาต้องตัดสินใจกลับมายังเมืองที่เขาเคยสาบานว่าจะปกป้องอีกครั้ง เพื่อล้างชะตากรรม ล้างความผิดที่ไม่ได้ก่อ และปกป้องภรรยากับลูกสาวที่เขารัก ทว่าอุปสรรคสำคัญคือการปรากฏตัวของ Dragon Prime ศัตรูลึกลับผู้ครอบครองพลังของผลึกมังกรขาวอีกครึ่งหนึ่ง ซึ่งจ้องจะแก้แค้นและทำลายล้าง White Dragon ให้สิ้นซาก', '2026-01-01', 5.60, 'https://image.tmdb.org/t/p/w342/yygzww0GACtCMmwhtPG1P01qSx5.jpg', 990.0000),
        (1124142, 'The Rivals of Amziah King', 'คนอย่างคิง', 'The Rivals of Amziah King', 'en', NULL, 'ลึกเข้าไปในพื้นที่ชนบทห่างไกลของรัฐโอคลาโฮมา แอมไซอาห์ คิง ผู้มีเสน่ห์และเปี่ยมพรสวรรค์ด้านดนตรี ได้รวบรวมกลุ่มนักดนตรีบลูแกรสส์นอกคอกเอาไว้ด้วยกัน พร้อมกับดูแลกิจการผลิตน้ำผึ้งอันดับหนึ่งของเมือง เมื่อลูกสาวบุญธรรมที่ห่างเหินกันไปกลับมาหาเขาอย่างไม่คาดคิด แอมไซอาห์จึงรีบคว้าโอกาสนี้เพื่อสานสัมพันธ์อีกครั้งและหมายมั่นจะสร้างธุรกิจครอบครัว แต่วงการค้าน้ำผึ้งนั้นโหดร้ายกว่าที่คิด และบรรดาคู่แข่งของแอมไซอาห์ก็พร้อมที่จะทำลายทุกสิ่งทุกอย่างที่เขาสร้างมา', '2026-01-01', 6.80, 'https://image.tmdb.org/t/p/w342/3iVDCDS1VwHIm95PjWEPwsfdhaf.jpg', 989.0000),
        (1433367, 'One Night Only', 'คืนเดียวเสียวรัก', 'One Night Only', 'en', NULL, 'โอเวน ชายหนุ่มที่เพิ่งอกหัก และอัลลี หญิงสาวผู้ยังไม่หมดศรัทธาในความรัก อาจเป็นคนโสดเพียงไม่กี่คนในเมืองที่กำลังมองหาบางสิ่งที่มีความหมายมากกว่าความสัมพันธ์เพียงชั่วข้ามคืน ทั้งคู่ต่างรู้สึกถึงแรงดึงดูดตั้งแต่วินาทีแรกที่ได้พบกัน แต่เหตุการณ์ไม่คาดฝัน ความเข้าใจผิด และเรื่องราววุ่นวายระหว่างทางกลับทำให้ทั้งสองต้องคลาดกันครั้งแล้วครั้งเล่า ขณะที่ต่างฝ่ายต่างวิ่งไล่ตาม และหลีกหนีกันไปทั่วมหานครนิวยอร์ก พวกเขาอาจค้นพบว่า สิ่งที่เฝ้าตามหามาตลอดนั้น แท้จริงแล้วอยู่ใกล้กว่าที่คิด', '2026-01-01', 6.50, 'https://image.tmdb.org/t/p/w342/f1v8IcYcQggeq1N0unoMJMrzTd9.jpg', 988.0000),
        (1598766, 'Crayon Shin-chan the Movie: Very Bizarre! My Yokai Vacation', 'เครยอนชินจัง เดอะมูฟวี่ ตอน ขนลุกซู่! วันหยุดพิศวงกับภูตผีกุ๊กกู๋', 'Crayon Shin-chan the Movie: Very Bizarre! My Yokai Vacation', 'en', NULL, 'ชินจังและครอบครัวเดินทางไปยังจังหวัดอาคิตะ บ้านเกิดของฮิโรชิ เพื่อชมเทศกาลดอกไม้ไฟโอมาการิอันเลื่องชื่อ แต่แล้วเหตุการณ์ประหลาดกลับทำให้เหล่าโยไค หรือภูตผีวิญญาณในตำนานญี่ปุ่น หลุดออกมาสร้างความวุ่นวายไปทั่วอาคิตะและลุกลามไปยังพื้นที่อื่น ๆ ของประเทศ ท่ามกลางความโกลาหล ชินจังและผองเพื่อนถูกดึงเข้าสู่โลกของโยไค และต้องออกผจญภัยสุดพิศวงในดินแดนเหนือธรรมชาติ ที่เต็มไปด้วยความลับและเรื่องราวเหนือความคาดหมาย', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/15iwqqJVgFfeFh4Y1f8gg9yi2Fw.jpg', 987.0000),
        (1484222, 'In the Name of Love', NULL, 'In the Name of Love', 'en', NULL, 'เรื่องราวการผจญภัยข้ามห้วงเวลาของพิมพ์มาดาหญิงสาวยุคปัจจุบันที่หลุดเข้าไปในโลกของวังวนรักแสนท็อกซิกของ “นางวันทอง” ในหน้าวรรณคดีที่สุดท้ายแล้วต้องรับโทษประหารเพราะขุนแผนและขุนช้างชายที่รักทั้งสอง แต่ทำไมต้องเป็นเธอที่ต้องก้มหน้ารับชะตากรรม พิมพ์มาดาจะขอกำหนดเส้นทางชีวิตใหม่ของวันทองด้วยความคิดและหัวใจของเธอเอง เพื่อหาทางเอาชีวิตรอดและหนีชะตาชีวิตอันน่าอดสูนี้ให้ได้', '2026-01-01', 1.00, 'https://image.tmdb.org/t/p/w342/qV8rbIOFs5Hs3SpmUBCeYGPmY7A.jpg', 986.0000),
        (1447853, 'Oasis: Don''t Look Back in Anger', 'ด๊อนท์ลุคแบคอินแองเกอร์', 'Oasis: Don''t Look Back in Anger', 'en', NULL, 'สัมผัสประสบการณ์การพุ่งทะยานของ โอเอซิส ผ่านทางฟุตเทจหายาก และเรื่องราวที่ไม่เคยถูกบอกเล่า ในขณะเดียวกันกับที่วงกลับมารวมตัวกันเพื่อทัวร์คอนเสิร์ต Oasis Live ''25 ไล่เรียงเรื่องราวการเดินทางของพวกเขาจากถนนของเมืองแมนเชสเตอร์ ไปสู่ความโด่งดังทั่วโลกในแวดวงร็อค', '2026-01-01', 7.50, 'https://image.tmdb.org/t/p/w342/5XoHhKZ1IROW6f5UlRpADHnTL2l.jpg', 985.0000),
        (1397485, 'Girls Like Girls', NULL, 'Girls Like Girls', 'en', NULL, 'โคลีย์ หญิงสาววัยสิบเจ็ดปีจากชนบทของโอเรกอน พบกับความสัมพันธ์อันชิดใกล้ หลังจากการเสียชีวิตของแม่ โดยการพบกับ ซอนย่า จุดประกายความรู้สึกใหม่หลาย ๆ อย่าง แต่ความสงสัยในตัวเองกลับเข้ามาขัดขวางความสัมพันธ์ของทั้งสอง เนื่องจาก ซอนย่า ไม่คุ้นเคยกับการเดทกับผู้หญิงมาก่อน ทำให้ทั้งสองต้องเรียนรู้ที่จะโอบรับอารมณ์ต่าง ๆ ไปพร้อม ๆ กัน', '2026-01-01', 7.50, 'https://image.tmdb.org/t/p/w342/gbP30EOIwUW0HZY9BwQMTRrk8uX.jpg', 984.0000),
        (426, 'Vertigo', 'พิศวาสหลอน', 'Vertigo', 'en', NULL, 'สก็อตตี้ สมัยยังเป็นนายตำรวจ เขาเป็นเหตุให้เพื่อนร่วมงานตกตึกตายขณะไล่ล่าคนร้ายบนตึกสูง ทำให้เขาเป็นโรคกลัวความสูง (Acrophobia) นับแต่นั้นมาและหันหลังให้อาชีพตำรวจ จนวันนึงเพื่อนเก่าของเขา เกวิน เอลส์เตอร์ เศรษฐีเจ้าของกิจการต่อเรือ ได้ว่าจ้างให้สก็อตตี้ตามสืบแฟนสาวของเขาที่มีพฤติกรรมแปลกประหลาดคล้ายโดนผีสิงชอบเดินทางไปสถานที่เดิมๆซ้ำๆว่าที่แท้เธอเป็นอะไรกันแน่', '2016-01-01', 8.10, 'https://image.tmdb.org/t/p/w342/15uOEfqBNTVtDUT7hGBVCka0rZz.jpg', 983.0000),
        (1491920, 'Kung Fu Soccer', 'กังฟูซอกเกอร์', 'Kung Fu Soccer', 'en', NULL, 'ทีมฟุตบอลหญิง “เอ๋อเหมย” เป็นทีมที่ไม่มีใครคาดหวังว่าจะประสบความสำเร็จ พวกเธอต้องลงแข่งขันในศึก “Supreme Invincible Cup” ซึ่งเต็มไปด้วยคู่แข่งฝีมือฉกาจและแรงกดดันจากรอบด้าน', '2026-01-01', 6.10, 'https://image.tmdb.org/t/p/w342/6QgJQrClh9ej357yzLWgCxrjAmJ.jpg', 982.0000),
        (1556321, 'Death Whisperer: Saming the Werebeast', NULL, 'Death Whisperer: Saming the Werebeast', 'en', NULL, 'ปี พ.ศ. 2511 ณ กาญจนบุรี ยักษ์ ทหารจากหน่วยเสือดำ ได้รับภารกิจด่วนจากพันตรีฤทธิ์ ให้ออกตามหานายทับ ทหารหน่วยข่าวกรองที่หายตัวไปในป่าลึกของเขาขวาง ซึ่งเป็นสถานที่ที่ขึ้นชื่อจากตำนานของ "ไอ้โหง" เสือสมิงแปลงร่างได้ ร่ำลือกันว่ามันมีพลังอมตะ ยักษ์และ จ่าปพันธ์ ได้นำหน่วยทหารชั้นยอดเข้าสู่ป่าลึกเพื่อตามหานายทหารที่หายสาบสูญและล่าอสูรกายกินคนที่ว่านี้ เมื่อเส้นแบ่งระหว่างคนกับอสูรกายเริ่มเลือนราง พวกเขาต้องต่อสู้เพื่อเอาชีวิตรอดจากความสยดสยองของไอ้โหง และปกป้องน้ำเพชร จากคมเขี้ยวของมัน', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/lN4YqCIVjDMvlUbmcEO5d060WoL.jpg', 981.0000),
        (1633056, 'All Wishes Come True!', '8 เซียน ขอให้จึ้ง!', 'All Wishes Come True!', 'en', NULL, 'ณ เผิงล่าย ดินแดนแห่งเทพเซียน มนุษย์ธรรมดา ๆ ทั้ง 8 คน ได้ปลอมตัวเป็นเซียน เพื่อหวังจะลักลอบเข้าไปในห้องเก็บสมบัติ ที่มีเฉพาะเทพเท่านั้นที่จะสามารถเข้าถึงได้ การแสวงหาทรัพย์มหาศาลได้นำพาพวกเขาไปสู่การเผชิญหน้ากับเทพผู้ทรงอิทธิพล บีบบังคับให้พวกเขาต้องใช้ไหวพริบและความเฉลียวฉลาดเล่ห์เหลี่ยมของมนุษย์ เพื่อเอาชนะกับอุปสรรคทั้งหลาย และกลายเป็นเหล่าเทพเซียนทั้ง 8', '2026-01-01', 7.90, 'https://image.tmdb.org/t/p/w342/wJ9FLxq3Q6D4ve8TUepYsr0PL3p.jpg', 980.0000),
        (1388805, 'LINKIN PARK: UNSHATTER', NULL, 'LINKIN PARK: UNSHATTER', 'en', NULL, 'After a seven-year hiatus following the devastating loss of their beloved bandmate Chester Bennington, LINKIN PARK''S remaining members struggled to find their way forward. Their shared history and enduring friendship, combined with the fresh perspective of two new band members Emily Armstrong and Colin Brittain spark a renewed creative energy that leads them on a transformative journey of artistic reinvention. Following the band from intimate 2022 studio sessions through their explosive FROM ZERO album release and concert in São Paulo, this documentary weaves together rare vault footage, electrifying performances from sold-out shows, and candid interviews with band members and fans—capturing the raw, honest story of what it means to start over.', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/kHNrz7DBVPrtyMhJxmBm2poS2l9.jpg', 979.0000),
        (1777750, 'Detective Conan: The Counterfeit Case of Ultra 30', NULL, 'Detective Conan: The Counterfeit Case of Ultra 30', 'en', NULL, 'As a new 10,000-yen banknote featuring the Touto Tower design is issued and the nation is swept up in excitement, Conan and the Junior Detective League, accompanied by Professor Agasa, Ran, and Sonoko, visit the Nagano factory of the Japan Banknote Printing Bureau. Meanwhile, counterfeit money is discovered at the scene of a murder in Tokyo, prompting the Metropolitan Police Department to establish an investigation headquarters. As the unprecedented circulation of counterfeit new banknotes throws the public into confusion, Conan and Heiji head to Osaka, where the counterfeit money is believed to have been printed.', '2026-01-01', 7.20, 'https://image.tmdb.org/t/p/w342/pT9RIHf4K9OyOB3eqYj97E5h0YA.jpg', 978.0000),
        (1307247, 'OK! Madam: Bon Voyage', 'แม่มาบู๊! กู้เรือนรก', 'OK! Madam: Bon Voyage', 'en', NULL, '"มียอง" อดีตสายลับระดับตำนาน ได้รับคำเชิญไปร่วมงานแต่งงานบนเรือสำราญพร้อมครอบครัว แต่ก่อนที่งานเฉลิมฉลองจะเริ่มต้น เรือทั้งลำกลับถูกแก๊งอาชญากรยึดกลางมหาสมุทร จากคุณแม่ธรรมดา...สู่สายลับที่ต้องกลับมาจับอาวุธอีกครั้ง เพื่อปกป้องครอบครัว ช่วยเหลือผู้โดยสาร และหยุดยั้งแผนการร้าย ก่อนที่เรือแห่งการเฉลิมฉลองจะกลายเป็นฝันร้าย', '2026-01-01', 5.50, 'https://image.tmdb.org/t/p/w342/8RvZG7YDPRi3NsVxkvi7zHlGltH.jpg', 977.0000),
        (1279865, 'A New Dawn', NULL, 'A New Dawn', 'en', NULL, 'The Obinata Fireworks Shop factory is getting prepared for an administrative action for confiscation tomorrow. It has been six years since Keitaro has been holed up in a closed-down factory creating fireworks by himself, chasing after an illusion of his father who vanished. It is a story about three young people who overcome the extreme weather conditions, disasters and environmental problems imposed on them and establish their own identities.', '2026-01-01', 7.20, 'https://image.tmdb.org/t/p/w342/tYGMWBZtLAPLhxZei9pRJWubbo0.jpg', 976.0000),
        (1623376, 'Blue Lock', 'ขังดวลแข้ง', 'Blue Lock', 'en', NULL, 'เมื่อวงการฟุตบอลญี่ปุ่นต้องการจุดเปลี่ยน ปฏิบัติการเฟ้นหา "เพชฌฆาตแดนหน้า" จึงเริ่มต้นขึ้น เด็กหนุ่มกองหน้าวัยมัธยมปลายตัวเทพ 300 ชีวิตถูกนำมาขังรวมกันไว้ในศูนย์ฝึกพิเศษที่ชื่อว่า "Blue Lock" เพื่อเข้าสู่โปรแกรมฝึกสุดโหด พวกเขาต้องดวลแข้งในเกมฟุตบอลที่มีอนาคตเป็นเดิมพัน เพราะในสนามรบแห่งนี้มีเพียง "ผู้ชนะที่เห็นแก่ตัวที่สุด" เท่านั้นที่จะได้ไปต่อ', '2026-01-01', 9.00, 'https://image.tmdb.org/t/p/w342/8EOuBxH8cqkVFdblOOduNsC0TuU.jpg', 975.0000),
        (1658653, 'Vanishing Point', 'คดีลึกตึกลับ', 'Vanishing Point', 'en', NULL, 'เรื่องราวสุดบีบคั้นที่เกิดขึ้นภายในอพาร์ตเมนต์แห่งหนึ่ง ได้เกิดเหตุการณ์ปริศนา 3 เรื่องขึ้นพร้อมกันในตึกเดียวกัน ทั้ง คดีเด็กหาย คดีทำร้ายร่างกาย และ คดีอำพรางศพ นำไปสู่การเผยความลับดำมืดของเพื่อนบ้าน', '2026-01-01', 6.30, 'https://image.tmdb.org/t/p/w342/v6Wq7P2UvgkEIczgS1fiHBzoJ1m.jpg', 974.0000),
        (1319525, 'Henry''s First Dates', NULL, 'Henry''s First Dates', 'en', NULL, 'เดทแรก เป็นช่วงเวลาที่น่าตื่นเต้นที่สุดของความสัมพันธ์ และความรู้สึกนี้จะเกิดขึ้นแค่ครั้งเดียวเท่านั้น! แต่ ''ลูซี่'' (มินนี่ ณิชา ยนตรรักษ์) เธอมีเดทแรกที่ไม่เหมือนใครในโลก เพราะเธอได้เดทกับ ''เฮนรี่'' (ณเดชน์ คูกิมิยะ) ชายหนุ่มอารมณ์ดี รักสัตว์ แต่ดันมีอาการแปลก ๆ ที่เมื่อตื่นขึ้นมาแล้วเขาจะจำเรื่องราวของเมื่อวานไม่ได้เลย  ลูซี่ จึงต้องหาทางจีบเฮนรี่ซ้ำซ้ำให้เขาตกหลุมรักเธอใหม่ในทุกวัน พร้อมยังต้องฝ่าด่านครอบครัวและคนสนิทอย่าง ป๋า (ซูโม่กิ๊ก เกียรติ กิจเจริญ) น้องขนุน (เบิ้ล ปทุมราช) และน้าสุ (ทิพากร ไชยประสิทธิ์) ไปให้ได้  งานนี้ลูซี่จะจีบซ้ำซ้ำติดมั้ย! แล้วเฮนรี่จะจำลูซี่ได้มั้ยนะ!', '2026-01-01', 6.00, 'https://image.tmdb.org/t/p/w342/zECf88Hy1ZTgzPe2kYpkscZckqh.jpg', 973.0000),
        (1684016, 'Katy Perry: The Lifetimes Tour – Live from Paris', NULL, 'Katy Perry: The Lifetimes Tour – Live from Paris', 'en', NULL, 'ขอเชิญพบกับภาพยนตร์คอนเสิร์ตที่เก็บรวบรวมภาพความประทับใจจาก Lifetimes Tour ทัวร์ของ Katy Perry ซึ่งบัตรหมดเกลี้ยงทุกที่นั่ง เต็มอิ่มไปกับ Katy Perry: The Lifetimes Tour – Live From Paris จาก Accor Arena กรุงปารีสเมื่อเดือนพฤศจิกายน 2025 ที่ผ่านมา กำกับโดย Paul Dugdale ผู้กำกับภาพยนตร์คอนเสิร์ตชื่อดัง ถ่ายทอดงานภาพจากกว่า 60 มุมกล้องเพื่อมอบประสบการณ์เต็มตาเต็มอารมณ์เหมือนได้ร่วมชมอยู่ในวันนั้นด้วยตัวเองที่แถวหน้าสุด', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/2nRLiwq897BFLRwLMIdA5TI3sX8.jpg', 972.0000),
        (1449433, 'Sound! Euphonium: The Final Movie, Part 1', 'ซาวด์ ยูโฟเนียม เดอะ ฟินาเล่ ปฐมบท', 'Sound! Euphonium: The Final Movie, Part 1', 'en', NULL, 'หลังจากฝ่าฟันการแข่งขันระดับภูมิภาคคันไซและคว้าสิทธิ์เข้าสู่การแข่งขันวงดุริยางค์ระดับประเทศได้สำเร็จ สมาชิกชมรมดุริยางค์โรงเรียนคิตาอุจิต่างเต็มเปี่ยมไปด้วยความหวังและแรงผลักดันสู่เป้าหมายสูงสุด นั่นคือ “เหรียญทองระดับประเทศ” ในช่วงเวลาที่ทุกคนกำลังมุ่งหน้าสู่เวทีแห่งความฝัน การมาถึงของ มายุ คุโรเอะ นักเรียนย้ายเข้าใหม่ กลับสร้างคลื่นความเปลี่ยนแปลงขึ้นภายในชมรม เธอเชื่อในการบรรเลงดนตรีที่ “ทุกคนสนุกไปด้วยกัน” แต่แนวคิดดังกล่าวกลับดูขัดแย้งกับแนวทางของวงคิตาอุจิที่ยึดถือระบบคัดเลือกตามความสามารถและความเท่าเทียมอย่างเคร่งครัด ท่ามกลางการเตรียมตัวสู่การแข่งขันระดับประเทศ ความรู้สึก ความฝัน และความเชื่อของสมาชิกแต่ละคนเริ่มปะทะกันอย่างหลีกเลี่ยงไม่ได้ ขณะที่ คุมิโกะ โอมาเอะ ในฐานะประธานชมรมปีสุดท้าย ต้องเผชิญกับบททดสอบครั้งสำคัญที่สุดในชีวิตนักดนตรีและชีวิตวัยรุ่นของเธอ', '2026-01-01', 8.00, 'https://image.tmdb.org/t/p/w342/3uFIhlbquYKH9jHBxTZ8afMfJmK.jpg', 971.0000),
        (1740257, 'NCT 127 5TH TOUR ‘NEO CITY  SEOUL - THE REDLINE’ in CINEMAS', NULL, 'NCT 127 5TH TOUR ‘NEO CITY  SEOUL - THE REDLINE’ in CINEMAS', 'en', NULL, 'Back after almost two years, NCT 127''s fifth tour,  NCT 127 5TH TOUR ‘NEO CITY : SEOUL - THE REDLINE’, is coming live to cinemas!  Experience the explosive energy, world-class performances, and electrifying atmosphere of KSPO DOME brought to life on the big screen with immersive sound.  NCTzens, join us for the spectacular kickoff of ''THE REDLINE''!', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/yvD0TWLNHlyP9dNHStjFV8v68nP.jpg', 970.0000),
        (1278971, 'God Skin', NULL, 'God Skin', 'en', NULL, 'Win, takes a lethal gamble to fund his mother''s medical treatment when Itt, an old friend, lures him into the Arena. In this brutal underground circuit, fighters are marked with "God Skin" tattoos to gain a ruthless edge.', '2026-01-01', 6.00, 'https://image.tmdb.org/t/p/w342/4giKVCl7repCb8NRc3EhE7M4le1.jpg', 969.0000),
        (1046304, '9 Temples to Heaven', NULL, '9 Temples to Heaven', 'en', NULL, 'A man takes his sick mother and nine family members on a single-day temple pilgrimage after his boss predicts she may die soon.', '2026-01-01', 10.00, 'https://image.tmdb.org/t/p/w342/6ofKFtLQCJC7xpRmMT1bzELP1cq.jpg', 968.0000),
        (1740876, 'Risen Up', NULL, 'Risen Up', 'en', NULL, '“สายลม” ยอดฮีโร่ผู้ต่อสู้กับองค์กรชั่วร้ายภายใต้คำสั่งของรัฐบาลเพื่อผดุงความยุติธรรม แต่ภารกิจใหม่ที่เขาต้องเผชิญ ทำให้เขาได้รู้ความจริงว่าสิ่งที่ตัวเองเชื่อมาตลอดนั้น “มันไม่ได้เป็นอย่างที่คิด”', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/juEsXxBgJzkmiqtzr3UbpoMVyFM.jpg', 967.0000),
        (1769154, 'ENHYPEN VR CONCERT : DESTINY', NULL, 'ENHYPEN VR CONCERT : DESTINY', 'en', NULL, 'On the night a crimson moon rises, ENHYPEN come face to face with the one destiny they have long awaited: ENGENE. Breaking the rules of the vampire world, they choose love and run away, only to face the same cruel fate again and again. Even with danger closing in as sharp as a “Knife,” the words they say to comfort each other, “Big Girls Don''t Cry,” lead them into a forbidden love called “CRIMINAL LOVE.” What ending awaits this love, sealed in blood?', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/uO42vQHjDQ1CYSdCiNUY5iP7YqO.jpg', 966.0000),
        (1736572, 'Midnight Incense', NULL, 'Midnight Incense', 'en', NULL, 'บริษัทแห่งนี้มีที่พักให้ฟรี แต่ทุกสิ่งล้วนมีราคา เพราะบ้านหลังนี้เก็บค่าเช่าด้วย "วิญญาณ" การได้ที่พักฟรีคือความโชคดี แต่นรกมักมาในรูปของ "ของแถม" บ้านเรือนไทยหลังนี้มีกฎเพียงข้อเดียว ทุก "00:00 น. ต้องจุดธูปหนึ่งดอก เพื่อรักษาชีวิต" ห้ามลืม… ห้ามช้า… เพราะถ้ากฎขาดเมื่อไหร่ พวกคุณต้องแลกด้วย "ชีวิต"', '2026-01-01', 1.00, 'https://image.tmdb.org/t/p/w342/aD7L1GCNk9Rt6jUEDNJmw3uQLdK.jpg', 965.0000),
        (1721536, 'The Resident', NULL, 'The Resident', 'en', NULL, 'ผู้ดูแลผู้ป่วยได้ดูแลผู้ป่วยร่ำรวยคนหนึ่งที่อาศัยอยู่ในคฤหาสน์ใหญ่เพียงลำพัง เธอได้เล่าเรื่องราวของผู้ป่วยให้แฟนหนุ่มผู้เป็นหนี้ได้ฟัง แฟนหนุ่มของเธอจึงได้ร่วมมือกับเพื่อนวางแผนปล้นคฤหาสน์ดังกล่าว แต่เมื่อเข้าไปกลับพบสิ่งที่ไม่คาดคิด', '2026-01-01', 1.00, 'https://image.tmdb.org/t/p/w342/mw9fsqQfhS6hMnCs611zrbePXiq.jpg', 964.0000),
        (1632627, 'UNME', NULL, 'UNME', 'en', NULL, 'ปีเตอร์ ติดอยู่ในห้องนอนกับบางสิ่งที่มีหน้าตาเหมือนเขา เขาต้องเอาตัวรอดผ่านค่ำคืนนี้ไปให้ได้ ก่อนความสยองจะมาเยือน', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/kQHJUtEmq2t5ej9Gr8Rt4fCdjF.jpg', 963.0000),
        (1555218, 'Are We Monsters?', NULL, 'Are We Monsters?', 'en', NULL, 'A gay radical outsider, a flamboyant Muslim, and a nasty single mom live in a devout Muslim area on the Thai border under decades of martial law.', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/lbrvikUasxWamMEofn1lJIswNgu.jpg', 962.0000),
        (1510215, 'POO-LICE STORY', 'นั่งส้วมซัด', 'POO-LICE STORY', 'en', NULL, 'โนอา รนรานเข้าห้องน้ำด้วยความปวดขี้ แต่เขาก็ถูกแซงคิวโดย หุ้น นักเลงกล้ามโต ทว่าความหวังก็ยังไม่สิ้นสุดเมื่อ ทอย ชายปริศนาปรากฏตัวออกมาจากห้องน้ำ และนั่นเป็นจุดเริ่มต้นของการต่อสู้ซัดชิงส้วม...', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/6T1tBkiIUPVqbIaO6qui3saACeq.jpg', 961.0000),
        (1301394, 'Regretfully At Dawn', NULL, 'Regretfully At Dawn', 'en', NULL, 'เรื่องราวชีวิตนอกเมืองกรุงของ ชายแก่หน้าตาบ้าน ๆ ผู้เป็นอดีตทหารผ่านศึกและยังคงมีแผลเป็นทั้งกายและใจจากอดีต ความฝันของเขาไม่มีอะไรมากมายนอกจากการสร้างบ้านต้นไม้ด้วยมือของเขาเอง พร้อมเลี้ยงถูกหลานสาวกำพร้า และเจ้าหมาสีดำที่ดวงตาของมันสามารถมองเห็นความลับของโลกหลังความตาย', '2026-01-01', 8.00, 'https://image.tmdb.org/t/p/w342/vdLZfwPig6K01BFGqv4QO1PVvY5.jpg', 960.0000),
        (1746438, 'The Space She Left Behind', NULL, 'The Space She Left Behind', 'en', NULL, 'เมื่อความตายพรากเพื่อนสนิทไปโดยไม่ทันร่ำลา เด็กชายวัยสิบขวบต้องเรียนรู้ที่จะอยู่กับพื้นที่ว่างที่เธอทิ้งไว้ ผ่านความฝันคืนหนึ่งที่เธอกลับมาโบกมือลา', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/s27nn9S5xLbAvyfRevS2IpLpKXh.jpg', 959.0000),
        (1760001, 'Songsakan', NULL, 'Songsakan', 'en', NULL, 'The film depicts the daily lives of a team that constructs and transports funeral palaces in northern Thailand. These Lanna-style funeral palaces form an essential part of the funeral procession and are eventually cremated together with the deceased. Beyond presenting the beliefs and traditions surrounding death in the region, the film also raises questions through its observation of funerals in various forms', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/mrZU5dhBCfJIS5GDQE28RWrbOay.jpg', 958.0000),
        (1741121, 'Can’t Sleep at Silent Night', NULL, 'Can’t Sleep at Silent Night', 'en', NULL, 'ในคืนหนึ่งภายในห้องนอนเล็กๆ ห้องหนึ่ง หญิงสาวคนหนึ่งกำลังนอนหลับอยู่บนเตียงอย่างสงบ ในขณะที่กำลังเกิดการประท้วงครั้งใหญ่ ผู้คนจำนวนมากรวมตัวกันอยู่บนท้องถนน  เสียงตะโกนโกรธเกรี้ยวของฝูงชนค่อยๆ เพิ่มขึ้นจนกลายเป็นความโกลาหล ก่อนที่สถานการณ์จะปะทุเป็นความรุนแรง', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/4nB84t7EyDkRxNbL2CgdqCZAo2V.jpg', 957.0000),
        (1748138, 'Black Beauty', NULL, 'Black Beauty', 'en', NULL, 'Sroy, a former famous actress known for her irresistible charm, discovers that her husband, Sin, a powerful and influential politician, has been secretly having an affair with a young female university student. She therefore joins forces with her Affair to bring them both public humiliation.', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/1S1PYhIKjzmp4hr1xkR9fCuyaWS.jpg', 956.0000),
        (1777536, 'Soundtrack to a Coup d’Etat 2', NULL, 'Soundtrack to a Coup d’Etat 2', 'en', NULL, 'A documentary about Thai political conflicts and the Thai monarch''s brilliance in jazz music.', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/rkGeX1ZOfPO071HLFnh09SYtDTW.jpg', 955.0000),
        (1763553, 'Temporary Nomad', NULL, 'Temporary Nomad', 'en', NULL, 'NOMADE AUF ZEIT follows Valentin on a two-year journey from Austria eastward. Traveling without a fixed plan, he hitchhikes, sleeps on strangers’ sofas and under open skies, and encounters an extraordinary range of people and their stories. At the heart of the film, however, is his time with a nomadic family deep in the mountains of Iran. Through his empathetic approach, Valentin manages to portray their daily life with remarkable intimacy.', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/f1szC4QGnpfV6DJX2Mi4qDCeSkR.jpg', 954.0000),
        (1781294, 'Hidden Paradise', NULL, 'Hidden Paradise', 'en', NULL, 'Naturalist Wan Chittiwat and ecologist Professor Kitichate Sridith embark on a journey across Thailand to uncover the country’s last remaining "hidden paradises", fragile ecosystems thriving outside protected areas yet disappearing under rapid development. From forgotten wetlands and coastal dune forests to seasonal floodplains sheltering species once thought extinct, the film reveals extraordinary biodiversity hidden in ordinary landscapes. Blending breathtaking natural history cinematography with an intimate documentary journey, Hidden Paradise challenges the idea that nature worthy of protection exists only within national parks, inviting audiences to rediscover the wild places that surround them before they disappear forever.', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/vUIwSKTQ7lFrkx6xLECv8dC0tr8.jpg', 953.0000),
        (969681, 'Spider-Man: Brand New Day', 'สไปเดอร์-แมน: แบรนด์ นิว เดย์', 'Spider-Man: Brand New Day', 'en', NULL, 'Spider-Man: Brand New Day คือการเปิดเรื่องราวบทใหม่ของปีเตอร์ พาร์คเกอร์ และสไปเดอร์-แมน สี่ปีผ่านไปนับตั้งแต่เหตุการณ์ใน Spider-Man: No Way Home ปีเตอร์เติบโตเป็นผู้ใหญ่เต็มตัว และใช้ชีวิตเพียงลำพังโดยสมบูรณ์ หลังจากเลือกที่จะลบตัวเองออกจากชีวิตและความทรงจำของคนที่เขารักทั้งหมด ด้วยการต่อสู้กับอาชญากรรมในมหานครนิวยอร์กที่ไม่มีใครจดจำชื่อของเขาได้อีกต่อไป เขาทุ่มเททุกอย่างให้กับการปกป้องเมืองของเขา ด้วยการเป็นสไปเดอร์-แมนเต็มตัว แต่เมื่อภาระหน้าที่ทวีความหนักหน่วง แรงกดดันกลับจุดชนวนให้เกิดการเปลี่ยนแปลงทางร่างกายอย่างคาดไม่ถึง ซึ่งอาจคุกคามการดำรงอยู่ของเขา ขณะเดียวกัน รูปแบบอาชญากรรมปริศนาแบบใหม่ก็เริ่มปรากฏ นำไปสู่ภัยคุกคามที่ทรงพลังที่สุดครั้งหนึ่งเท่าที่เขาเคยเผชิญ', '2026-01-01', 7.90, 'https://image.tmdb.org/t/p/w342/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg', 952.0000),
        (1368337, 'The Odyssey', 'มหากาพย์โอดิสซี', 'The Odyssey', 'en', NULL, 'เรื่องราวที่ดัดแปลงมาจากบทกวีมหากาพย์ชื่อเดียวกันของ โฮเมอร์ ติดตามเรื่องราวของ โอดิสเซียส​ ในการเดินทางกลับบ้านที่แสนอันตราย หลังจากสงครามโทรจัน เปิดเผยให้เห็นถึงการเผชิญหน้าของเขากับ โพลีฟีมัส, เหล่าไซเรน, เซอร์ซี และสิ้นสุดด้วยการกลับมาพบกับ เพเนโลพี ภรรยาของเขาอีกครั้ง', '2026-01-01', 8.00, 'https://image.tmdb.org/t/p/w342/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg', 951.0000),
        (1101383, 'The End of Oak Street', 'มหาภัยสุดถนนโอ๊ค', 'The End of Oak Street', 'en', NULL, 'เรื่องราวที่เกิดขึ้นเมื่อเหตุการณ์ลึกลับจากห้วงอวกาศได้กระชากถนนโอ๊ค ออกจากย่านชานเมือง และเหวี่ยงชุมชนของพวกเขาไปยังสถานที่ที่ไม่มีใครรู้จัก ครอบครัวแพลตต์จึงได้ค้นพบในไม่ช้าว่า การเอาชีวิตรอดของพวกเขาขึ้นอยู่กับการร่วมแรงร่วมใจกัน เพื่อฝ่าฟันและหาทางออกจากสภาพแวดล้อมที่พวกเขาไม่คุ้นเคย', '2026-01-01', 7.10, 'https://image.tmdb.org/t/p/w342/fYXqpgPmHMphSF2W30GbTeJVIa5.jpg', 950.0000),
        (1032863, 'The Love Hypothesis', 'สมมติฐานแห่งความรัก', 'The Love Hypothesis', 'en', NULL, 'สร้างจากนิยายขายดีของเดอะนิวยอร์กไทมส์ สมมติฐานแห่งความรักเล่าเรื่องราวของโอลีฟนักศึกษาปริญญาเอกที่เผลอจูบอดัม คาร์ลเซนศาสตราจารย์มาดขรึมที่น่าเกรงขามที่สุดในภาควิชา ความจำเป็นของทั้งคู่ที่ต้องแกล้งคบกันจึงกลายเป็นการทดลองทางเคมีที่อาจนำไปสู่คำตอบของสมการรักจริงๆ', '2026-01-01', 8.20, 'https://image.tmdb.org/t/p/w342/vfZxVHextAGC70zrNhS8lsROqP1.jpg', 949.0000),
        (1204680, 'Coyote vs. Acme', 'โคโยตี้ ปะทะ แอคมี่', 'Coyote vs. Acme', 'en', NULL, 'เมื่อ "ไวล์ อี. โคโยตี้" หมาป่าดวงซวย หมดความอดทนกับการเจ็บตัวซ้ำซาก จึงตัดสินใจยื่นฟ้องศาลเรียกค่าเสียหายจากบริษัทแอคมี่ ข้อหาผลิตสินค้าห่วยและไม่ได้มาตรฐาน โดยมีทนายดวงตก เควิน และ เพจ เอเวอรี่ หลานสาวไฟแรง มาช่วยสู้คดีปะทะกับทนายฝั่งบริษัทใหญ่อย่าง บัดดี้ เครน', '2026-01-01', 7.60, 'https://image.tmdb.org/t/p/w342/kYDCl2y0VPvhT5eYWbMRInPoB03.jpg', 948.0000),
        (1751701, 'After Impact', NULL, 'After Impact', 'en', NULL, 'After losing his father, Ethan Nichols inherits one of the largest greenhouses in the country, just as the world faces a devastating threat from an approaching asteroid. As society begins to unravel, Ethan grapples with personal betrayal, overwhelming loneliness, and the growing fear that survival may come at the cost of his humanity. Seeking refuge in his family’s bunker, Ethan endures the harsh aftermath of the impact, wrestling with physical injury and emotional despair. When a faint voice crackles over his radio, Ethan discovers he''s not as alone as he believed.', '2026-01-01', 6.40, 'https://image.tmdb.org/t/p/w342/yzDuAQCY2n6zzOlBkn6JzhLhY3k.jpg', 947.0000),
        (1228834, 'The Fix', NULL, 'The Fix', 'en', NULL, 'Disillusioned by the end of the war in Afghanistan, a group of disgraced, war-torn ex-CIA operatives set out to Tehran to take down a life-changing score.', '2026-01-01', 7.10, 'https://image.tmdb.org/t/p/w342/9iSkee8DPpwBQI3GhXSTGZJKNYM.jpg', 946.0000),
        (1294189, 'The Mongoose', NULL, 'The Mongoose', 'en', NULL, 'A falsely accused war hero with nothing to lose leads police on an epic televised cross-country car chase, helped by members of his former Special Forces Army battalion and closely monitored by a fascinated public rooting for his safe getaway.', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/eSS5mvSG84UUuvtbHel5Yu3Wik4.jpg', 945.0000),
        (1375646, 'Colony', 'ยึดร่างคลั่ง', 'Colony', 'en', NULL, 'เซจอง ศาสตราจารย์ด้านเทคโนโลยีชีวภาพ ได้เข้าร่วมงานประชุมชีวภาพ เพียงเพื่อที่จะเห็นมันกลายมาเป็นความหายนะ เมื่อไวรัสที่กลายพันธุ์อย่างรวดเร็วได้ถูกปลดปล่อยออกมา ในขณะที่การแพร่ระบาดได้เกิดขึ้นและเหล่าผู้ติดเชื้อเริ่มที่จะกลายร่าง ทางผู้มีอำนาจก็ได้สั่งปิดสถานที่แห่งนี้ ทำให้ผู้รอดชีวิตต้องติดอยู่กับภัยอันตรายที่น่ากลัวขึ้นในทุกวินาที', '2026-01-01', 8.10, 'https://image.tmdb.org/t/p/w342/tN799oUR0f1gUKDYdMNrDaY7I51.jpg', 944.0000),
        (1084244, 'Toy Story 5', 'ทอย สตอรี่ 5', 'Toy Story 5', 'en', NULL, 'เหล่าของเล่นกลับมาอีกครั้งในภาพยนตร์เรื่อง "Disney and Pixar’s Toy Story 5 ทอยสตอรี่ 5" และครั้งนี้คือการเผชิญหน้าระหว่าง ของเล่นและเทคโนโลยี Woody (พากย์เสียงโดย Tom Hanks), Buzz Lightyear (พากย์เสียงโดย Tim Allen), Jessie (พากย์เสียงโดย Joan Cusack) และผองเพื่อน ต้องเผชิญกับความท้าทายครั้งใหม่ เมื่อพวกเขาได้พบกับ Lilypad (พากย์เสียงโดย Greta Lee) อุปกรณ์แท็บเล็ตรุ่นใหม่ที่เข้ามาพร้อมแนวคิดของตัวเองเกี่ยวกับสิ่งที่ดีที่สุดสำหรับเด็กน้อยของพวกเขาอย่าง Bonnie แล้วแบบนี้ ช่วงเวลาแห่งการเล่นจะยังคงเหมือนเดิมอีกหรือไม่', '2026-01-01', 8.30, 'https://image.tmdb.org/t/p/w342/sfQtVlIHljToOwYjhe21KPGzZWK.jpg', 943.0000),
        (1492640, 'UNABOMBER', 'ยูนาบอมเมอร์', 'UNABOMBER', 'en', NULL, 'ในผลงานดราม่าที่ได้แรงบันดาลใจจากเรื่องจริง เท็ด คาซินสกีค่อยๆ เปลี่ยนจากอัจฉริยะแห่งฮาร์วาร์ดและผู้เข้าร่วมการทดลอง มาเป็น "ยูนาบอมเมอร์" ผู้ก่อการร้ายที่เอฟบีไอตามล่า', '2026-01-01', 6.90, 'https://image.tmdb.org/t/p/w342/39aMkR8Y5vhCG9dTkjiqRl8AVqp.jpg', 942.0000),
        (1377237, 'Runner', 'พี่บึ้ก… โคตรคน ชนนรก', 'Runner', 'en', NULL, 'แฮงก์ มาโลน อดีตทหารฝีมือฉกาจ ต้องรับภารกิจขนส่งอวัยวะทางการแพทย์เพื่อช่วยชีวิตเด็กหญิงคนหนึ่ง แต่ภารกิจที่ควรจะเป็นเพียงการส่งของกลับกลายเป็นการไล่ล่าสุดระห่ำ เมื่อเขาและเบน บิช็อป คู่หูจำเป็นที่เข้ากันไม่ค่อยได้ กลายเป็นเป้าหมายของแก๊งค้ายาเสพติดสุดโหด ทั้งสองต้องฝ่าดงกระสุน หลบหนีการตามล่า และรับมือกับการหักหลังที่เกิดขึ้นรอบตัว ท่ามกลางเวลาที่เหลือน้อยลงทุกขณะ เพราะความผิดพลาดเพียงครั้งเดียวอาจหมายถึงชีวิตของเด็กหญิงที่กำลังรอความช่วยเหลือ', '2026-01-01', 8.00, 'https://image.tmdb.org/t/p/w342/yBKMAIj7clP42UkFejhGDBBoTpb.jpg', 941.0000),
        (1607127, 'One Last Shot', 'ยุทธการนัดสุดท้าย', 'One Last Shot', 'en', NULL, 'เจค แฮร์ริส หน่วยซีลผู้ช่ำชอง ถูกเรียกกลับมาปฏิบัติการอีกครั้ง เมื่ออดีตสหายกลายเป็นภัยคุกคามต่อโลก เพื่อหยุดยั้งผู้บงการไม่ให้ได้รหัสนิวเคลียร์ แฮร์ริสต้องนำทีมบุกแดนศัตรู ฝ่ากองทัพทหารรับจ้าง กับดักมรณะ และเผชิญหน้ากับอดีตอันมืดมนของตนเอง', '2026-01-01', 7.40, 'https://image.tmdb.org/t/p/w342/niQ4NBh2jqAf1hDZP5m6ReWFAb7.jpg', 940.0000),
        (1339713, 'Obsession', 'สาปรักคลั่งหลอน', 'Obsession', 'en', NULL, 'หลังจากที่ได้ทำลายของเล่นลึกลับที่มีชื่อว่า วัน วิช วิลโลว์ เพื่อที่จะเอาชนะใจหญิงสาวที่เขาตกหลุมรัก ชายผู้เชื่อมั่นในรักแท้คนหนึ่งก็ได้ในสิ่งที่เขาต้องการมา แต่ไม่นานนักเขาก็พบว่า ความต้องการบางอย่างมาพร้อมกับราคาอันน่าสยดสยองที่ต้องจ่าย', '2026-01-01', 8.20, 'https://image.tmdb.org/t/p/w342/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', 939.0000),
        (460458, 'Resident Evil: Welcome to Raccoon City', 'ผีชีวะ ปฐมบทแห่งเมืองผีดิบ', 'Resident Evil: Welcome to Raccoon City', 'en', NULL, 'ในปี 1998 ผู้อยู่อาศัยในแร็คคูนซิตี้ต้องหาทางเอาชีวิตรอดจากค่ำคืนหฤโหด ขณะที่บริษัทเภสัชกรรมพยายามปกปิดความผิดพลาดและลบล้างหลักฐานที่ก่อ', '2022-01-01', 5.90, 'https://image.tmdb.org/t/p/w342/bArhvjRHl535XMaSh9VjInF2mSZ.jpg', 938.0000),
        (1482547, 'Zip Wire', NULL, 'Zip Wire', 'en', NULL, 'When her ground-breaking pharmaceutical discovery is stolen and partner murdered, researcher Amy must face her fear of heights to escape nefarious attackers, with the only path to salvation being a treacherous aerial runway. To outsmart the mysterious hostiles, she has to summon every ounce of courage to protect the world-changing scientific discovery — and herself — before it''s too late.', '2026-01-01', 7.30, 'https://image.tmdb.org/t/p/w342/cO7J0XSVKPlAjUCMWC7DVBn1Py2.jpg', 937.0000),
        (1477712, 'Ice Cream Man', 'หวานเย็น เข็นมาเชือด', 'Ice Cream Man', 'en', NULL, 'เมืองฤดูร้อนอันสงบสุขต้องร่วงหล่นลงไปในความบ้าคลั่ง เมื่อคนขายไอศกรีมคนหนึ่งได้ขายของหวานชวนชื่นใจที่มาพร้อมกับผลลัพธ์อันน่าสยดสยอง', '2026-01-01', 4.70, 'https://image.tmdb.org/t/p/w342/lNBxToxHWrzmkqeFnf1XADUTxQq.jpg', 936.0000),
        (1108427, 'Moana', 'โมอาน่า', 'Moana', 'en', NULL, 'มหาสมุทรเลือกเธอเพราะมีเหตุผล ร่วมออกผจญภัยสุดตระการตาไปบนท้องทะเลโอเชียเนีย กับภารกิจที่แสนอันตรายและน่าตื่นเต้น', '2026-01-01', 7.40, 'https://image.tmdb.org/t/p/w342/gaet1xQ2nxrG0V1Ep9T20ZMNEIC.jpg', 935.0000),
        (1232569, 'Pinocchio: Unstrung', 'พินอคคิโอ หุ่นไม้สายเชือด', 'Pinocchio: Unstrung', 'en', NULL, 'เรื่องราวหักมุมของหุ่นไม้คลาสสิกที่ถูกปลุกชีพขึ้นมาด้วยมนต์ดำ แต่แทนที่มันจะอยากเรียนรู้การเป็นเด็กดีเพื่อเป็นมนุษย์ พินอคคิโอกลับมีความปรารถนาอันแรงกล้าที่จะเป็น "เด็กผู้ชายที่มีเนื้อหนังจริงๆ" ทว่าวิธีการได้มาซึ่งเนื้อหนังและอวัยวะมนุษย์ของมันคือการออกไล่ฆ่า ชำแหละ และเอาชิ้นส่วนของเหยื่อมาเติมเต็มร่างกายตัวเอง กลายเป็นหุ่นไม้ฆาตกรสุดโหดที่ไม่สนสายใยหรือคำสอนใดๆ ทั้งสิ้น เพราะมันยอมฆ่า เพื่อให้ได้เป็นเด็กจริง ๆ', '2026-01-01', 6.60, 'https://image.tmdb.org/t/p/w342/eUJXk3bTvLBi5Zcb0BCedZU7lVL.jpg', 934.0000),
        (1240889, 'Teenage Sex and Death at Camp Miasma', 'มิอัสมา ค่ายสยองของสองเรา', 'Teenage Sex and Death at Camp Miasma', 'en', NULL, 'หลังจากหลายปีของหนังภาคต่อที่ถูกทำออกมาอย่างลวก ๆ และกลุ่มแฟนคลับที่ค่อย ๆ จางหายไป แฟรนไชส์ภาพยนตร์ไล่เชือด มิอัสมา ก็ถูกส่งต่อมายังผู้กำกับสาวเพื่อปลุกชีวิตมัน แต่ในตอนที่เธอเดินทางไปหานักแสดงนำของภาพยนตร์ภาคต้นฉบับ ที่ในตอนนี้กลายมาเป็นนักแสดงผู้สันโดษที่ปกคลุมไปด้วยปริศนา หญิงทั้งสองคนก็ร่วงหล่นลงไปในโลกเปื้อนเลือดที่เต็มไปด้วยความปรารถณา, ความกลัว และความเพ้อคลั่ง', '2026-01-01', 6.40, 'https://image.tmdb.org/t/p/w342/6Q6Zo6GNXMLP600OJSh6MhW21um.jpg', 933.0000),
        (1440098, 'Drawn Together', 'มาร์ฟิล: แรงดึงดูดระหว่างเรา', 'Drawn Together', 'en', NULL, 'มาร์ฟิล ลูกสาวนักธุรกิจทรงอิทธิพลชาวสเปนพบว่าชีวิตตนเองในนิวยอร์กกลับตาลปัตร เมื่อเธอถูกลักพาตัวและปล่อยตัวโดยไม่มีคำอธิบาย พ่อของเธอจ้างเซบาสเตียน มัวร์ให้เป็นบอดี้การ์ดของเธอ และบังคับให้ใช้เวลาร่วมกันทุกนาที พวกเขาเจอแรงดึงดูดเกินต้านทานต่อกันในโลกซึ่งทุกอย่างไม่เป็นอย่างที่เห็น สร้างจากหนังสือของเมร์เซเดส รอน นักเขียนเจ้าของหนังสือชุดคัลเพเบิลส์', '2026-01-01', 6.80, 'https://image.tmdb.org/t/p/w342/6rpvddXbaQPOi0fB2HKWbZ3uUSg.jpg', 932.0000),
        (82976, 'The Novices', NULL, 'The Novices', 'en', NULL, 'Sister Agnès runs away from her convent in Brittany and seeks refuge in Paris with prostitute Mona Lisa. With absolutely no qualifications, the young novice has a hard job finding work, so Mona Lisa tries to teach her the ropes of the oldest profession of them all!', '1970-01-01', 4.80, 'https://image.tmdb.org/t/p/w342/a2SnSbRxMB4vktOxZapaspY2fTC.jpg', 931.0000),
        (687163, 'Project Hail Mary', 'ภารกิจกู้สุริยะ', 'Project Hail Mary', 'en', NULL, 'คุณครูวิชาวิทยาศาสตร์ ไรแลนด์ เกรซ ตื่นขึ้นมาบนยานอวกาศที่อยู่ห่างไกลจากโลกหลายล้านปีแสง โดยที่ไม่มีความทรงจำว่าเขาคือใคร หรือเขามาอยู่ที่นี่ได้อย่างไร ในขณะที่ความทรงจำของเขาเริ่มกลับคืนมา เขาก็เริ่มที่จะเข้าใจถึงภารกิจของเขา คือ การไขปริศนาของสารลึกลับบางอย่างที่กำลังทำให้ดวงอาทิตย์มอดดับลง เขาต้องใช้ความรู้ทางวิทยาศาสตร์ทั้งหมดที่เขามี และความคิดนอกขนบเพื่อที่จะช่วยเหลือทุกชีวิตบนโลกจากการสูญพันธุ์ แต่มิตรภาพที่คาดไม่ถึงที่เข้ามา ก็หมายความว่าเขาอาจจะไม่ต้องทำมันเพียงแค่คนเดียว', '2026-01-01', 8.60, 'https://image.tmdb.org/t/p/w342/iOb2fjXLbpJgyQXe46n1WtGCnaa.jpg', 930.0000),
        (1083381, 'Backrooms', 'นรกห้องลับ', 'Backrooms', 'en', NULL, 'ประตูประหลาดปรากฏขึ้นมาในชั้นใต้ดินของโชว์รูมฟอร์นิเจอร์', '2026-01-01', 7.00, 'https://image.tmdb.org/t/p/w342/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg', 929.0000),
        (1315772, 'Minions & Monsters', 'มินเนี่ยน & มอนสเตอร์', 'Minions & Monsters', 'en', NULL, 'นี่คือเรื่องราวแสนชุลมุนอย่างล้นเหลือ, น่าขบขัน และเป็นเรื่องจริงอย่างแน่นอน กับการที่เหล่า มินเนี่ยน ครอบครองฮอลลีวูด, กลายมาเป็นดาราเบอร์ใหญ่, สูญเสียทุกอย่าง, ปลดปล่อยสัตว์ประหลาดออกไปสู่โลก แล้วหลังจากนั้นก็รวมตัวกันเพื่อพยายามที่จะช่วยเหลือดาวเคราะห์ดวงนี้จากความวุ่นวายที่พวกเขาเพิ่งจะสร้างขึ้น', '2026-01-01', 7.60, 'https://image.tmdb.org/t/p/w342/4LwvU9SZc8QQzW1X1FAPhNbXnEU.jpg', 928.0000),
        (1224993, 'Dark Nuns', 'ไล่มันกลับลงหลุม', 'Dark Nuns', 'en', NULL, 'เพื่อช่วยเหลือเด็กชายที่ถูกวิญญาณร้ายเข้าสิง แม่ชี ยูเนีย ต้องเผชิญกับอันตรายที่คาดไม่ถึง เธอมุ่งมั่นจะช่วยเด็กคนนั้นด้วยความช่วยเหลือจากแม่ชี มิคาเอลา แม้ว่าจะต้องทำพิธีกรรมต้องห้ามก็ตาม ท่ามกลางความโกลาหลที่รายล้อมพวกเธอ บาทหลวง พอล ผู้เป็นนักนักจิตเวช ยืนกรานว่าการรักษาทางการแพทย์เท่านั้นที่เป็นคำตอบ โดยปฏิเสธแนวคิดเรื่องการถูกผีสิง ในขณะที่บาทหลวง อันเดรีย ยืนยันว่ามีเพียงการไล่ผีเท่านั้นที่จะปลดปล่อยเด็กชายจากความทุกข์ทรมานได้', '2025-01-01', 6.20, 'https://image.tmdb.org/t/p/w342/2Abt2GgscAGtGAXTrhH44qPhugI.jpg', 927.0000),
        (1538457, 'Meesaya Murukku 2', NULL, 'Meesaya Murukku 2', 'en', NULL, 'After facing rejection in love and getting into a fight, Jeeva learns about his father Siva''s struggles and sacrifices. Inspired by his grandfather''s legacy and father''s dedication, Jeeva changes his outlook and works hard toward his musical dream. Through determination and perseverance, Jeeva earns recognition in the music industry and brings pride to his family.', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/qD1QwmInB9ezd2peVb5EbhaM4Mo.jpg', 926.0000),
        (299536, 'Avengers: Infinity War', 'อเวนเจอร์ส: มหาสงครามล้างจักรวาล', 'Avengers: Infinity War', 'en', NULL, 'เหล่าอเวนเจอร์ยังคงต้องปกป้องโลกจากภัยอันตรายครั้งใหญ่ที่เกินกว่าที่ซุปเปอร์ฮีโร่คนเดียวจะรับมือได้ อันตรายครั้งใหม่นั้นมาจากเงามืดของจักรวาล ‘ทานอส’ จอมเผด็จการแห่งจักรวาล เป้าหมายของเขาคือการรวบรวมอัญมณี อินฟินิตี้สโตนส์ทั้งหก เพื่อครอบครองพลังที่เกินจะจินตนาการถึง และใช้พวกมันในการเปลี่ยนแปลงความจริงทั้งมวลของจักรวาล ทุกสิ่งทุกอย่างที่อเวนเจอร์ต่อสู้มาก็เพื่อสิ่งนี้ ชะตากรรมของโลกและจักรวาลไม่เคยสั่นคลอนเท่านี้มาก่อน', '2018-01-01', 8.20, 'https://image.tmdb.org/t/p/w342/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', 925.0000),
        (1375441, 'Primetime', NULL, 'Primetime', 'en', NULL, 'In 2006, To Catch a Predator host Chris Hansen sets out to make television history, turning an undercover investigation into one of the most controversial cultural phenomena of the decade.', '2026-01-01', 7.20, 'https://image.tmdb.org/t/p/w342/lmrulvLbmaejTix1YaMxo1oGhH1.jpg', 924.0000),
        (335984, 'Blade Runner 2049', 'เบลด รันเนอร์ 2049', 'Blade Runner 2049', 'en', NULL, 'Blade Runner 2049 ว่าด้วยเรื่องราวต่อจาก 30 ปีที่แล้ว บริษัทไทเรล ล่มสลายจากการก่อกบฎทำให้เกิดข้อห้ามการสร้างมนุษย์เทียม กาลเวลาผ่านไป ถือกำเนิดบริษัทใหม่ Wallace Corporation นำโดย ไนแอนเดอร์ วอลเลซ (รับบทโดย จาเร็ด เลโต) เข้ามาแทนที่ เขาได้ดีงเอาเทคโนโลยีของไทเรลมาผนวกกับวิสัยทัศน์ใหม่ และได้เริ่มผลิตมนุษย์เทียมรุ่น Nexus-9 ขึ้นมา พร้อมออกกฎให้ปราบปรามหุ่นรุ่นเก่าอันเป็นต้นเหตุของการก่อกบฎให้หมดสิ้น', '2017-01-01', 7.60, 'https://image.tmdb.org/t/p/w342/gajva2L0rPYkEWjzgFlBXCAVBE5.jpg', 923.0000),
        (1580190, 'The Scavenger', NULL, 'The Scavenger', 'en', NULL, 'When his aspiring-celebrity sister becomes trapped in a criminal scheme within an entertainment company, a devoted brother teams up with local police to uncover the truth and take down the powerful underworld behind it.', '2026-01-01', 2.00, 'https://image.tmdb.org/t/p/w342/oaZbbcJUKgw95EGIT7VTPLEzuB3.jpg', 922.0000),
        (1465063, 'Forgotten Island', 'เกาะมหัศจรรย์กับความทรงจำที่ลบลืม', 'Forgotten Island', 'en', NULL, 'เรื่องราวของเพื่อนรักสองคนที่ติดอยู่ในโลกลี้ลับที่มีชื่อว่า นาคาลี ที่ซึ่งหนทางออกจากที่นี่ของทั้งสอง อาจจะหมายถึงการสูญเสียความทรงจำชั่วชีวิตที่มีเคยมีร่วมกันมา', '2026-01-01', 8.10, 'https://image.tmdb.org/t/p/w342/Lr0Ng7Gg02RW1AyfYEL6P0WUvd.jpg', 921.0000),
        (1003596, 'Avengers: Doomsday', 'อเวนเจอร์ส ดูมส์เดย์', 'Avengers: Doomsday', 'en', NULL, 'Beloved heroes from three distinct universes are set on a deadly collision course and face an existential threat unlike anything they''ve ever encountered.', '2026-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/jzPwsojjFStf5lR5Nm07w2hH56G.jpg', 920.0000),
        (755898, 'War of the Worlds', 'สงครามโลก', 'War of the Worlds', 'en', NULL, 'วิลล์ แรดฟอร์ด เป็นนักวิเคราะห์ความปลอดภัยทางไซเบอร์ชั้นนำของกระทรวงความมั่นคงแห่งมาตุภูมิ ผู้ติดตามภัยคุกคามที่อาจเกิดขึ้นต่อความมั่นคงแห่งชาติผ่านโครงการเฝ้าระวังมวลชน จนกระทั่งวันหนึ่ง การโจมตีจากบุคคลที่ไม่รู้จัก ทำให้เขาตั้งคำถามว่ารัฐบาลกำลังปิดบังอะไรบางอย่างจากเขา... และจากส่วนอื่นๆ ของโลกหรือไม่', '2025-01-01', 4.00, 'https://image.tmdb.org/t/p/w342/yvirUYrva23IudARHn3mMGVxWqM.jpg', 919.0000),
        (1469930, 'Project Sacrifice', NULL, 'Project Sacrifice', 'en', NULL, 'While investigating their father’s death inside a major bridge construction company, Yuda and his family attempt to prove that the frequent, deadly workplace accidents are actually human sacrifices.', '2026-01-01', 3.90, 'https://image.tmdb.org/t/p/w342/321rzg1B6RRhcuRgsFHjQ7Xl3XX.jpg', 918.0000),
        (1641629, 'You+Me - Against the World', NULL, 'You+Me - Against the World', 'en', NULL, 'Alma Lancaster, 18, appears to lead a perfect life within a wealthy family who believes she is studying law. In secret, she pursues her true dream: filmmaking. On campus, she meets Vadim Arcadi, 20, a magnetic and solitary rebel with a troubled past. Forced to collaborate on a student film, they clash, grow closer and fall in love — despite themselves. But someone is watching them, determined to tear them apart and expose secrets that could destroy both Alma and Vadim.', '2026-01-01', 5.80, 'https://image.tmdb.org/t/p/w342/bAbBNVplg7h79sm94OyHeKk8Phz.jpg', 917.0000),
        (233651, 'Sex Rider: Wet Highway', NULL, 'Sex Rider: Wet Highway', 'en', NULL, 'On the eve of her wedding and while cheating with another man, a woman gets involved into a dangerous new world of experiences.', '1971-01-01', 5.00, 'https://image.tmdb.org/t/p/w342/jmyo0j2HMDeFvMh5y1wFYpoxH6S.jpg', 916.0000),
        (591634, 'False Positive', NULL, 'False Positive', 'en', NULL, 'After months of trying and failing to get pregnant, Lucy and Adrian finally find their dream fertility doctor in the illustrious Dr. Hindle. But after becoming pregnant with a healthy baby girl, Lucy begins to notice something sinister through Hindle''s gleaming charm, and she sets out to uncover the unsettling truth about him.', '2021-01-01', 5.60, 'https://image.tmdb.org/t/p/w342/3HSov8EW2fI3oQbUJxOvnf684ej.jpg', 915.0000),
        (83533, 'Avatar: Fire and Ash', 'อวตาร: อัคนีและธุลีดิน', 'Avatar: Fire and Ash', 'en', NULL, 'ท่ามกลางสงครามอันโหดร้ายกับ RDA และความโศกเศร้าจากการสูญเสียลูกชายคนโต เจค ซัลลี่ และ เนย์ทีรี จะต้องพบกับภัยคุกคามใหม่บนดาวแพนโดร่า เหล่าชาวนาวีเผ่าขี้เถ้าที่ป่าเถื่อนและกระหายในอำนาจ นำโดยหัวหน้าเผ่าผู้เหี้ยมโหดที่มีชื่อว่า วารัง ครอบครัวของ เจค จะต้องต่อสู้เพื่อเอาชีวิตรอดและเพื่ออนาคตของดาวแพนโดร่า ในความขัดแย้งที่จะผลักดันทุกคนไปยังขีดสุดของทั้งร่างกายและจิตใจ', '2025-01-01', 7.60, 'https://image.tmdb.org/t/p/w342/bRBeSHfGHwkEpImlhxPmOcUsaeg.jpg', 914.0000),
        (1275779, 'Disclosure Day', 'วันเปิดโปง: ไขปริศนาลวงโลก', 'Disclosure Day', 'en', NULL, 'ถ้าคุณพบว่าพวกเราไม่ได้อยู่เพียงลำพัง ถ้าหากว่ามีใครสักคนแสดงให้คุณได้เห็น พิสูจน์มันให้กับคุณ นั่นจะทำให้คุณหวาดผวาหรือไม่? ฤดูร้อนนี้ ความจริงจะเป็นของผู้คนทั้งเจ็ดพันล้านคน พวกเรากำลังจะเข้าใกล้วันเปิดโปงขึ้นทุกทีแล้ว', '2026-01-01', 7.50, 'https://image.tmdb.org/t/p/w342/AnJ8IQJI23hNpYXVNaythu061Ru.jpg', 913.0000),
        (1248832, 'Digger', 'ดิกเกอร์', 'Digger', 'en', NULL, 'ชายผู้ทรงอำนาจที่สุดในโลกต้องออกเดินทางไปทำภารกิจสุดบ้าคลั่ง เพื่อที่จะพิสูจน์ว่าเขาคือคนที่จะมาช่วยเหลือมนุษย์ชาติ ก่อนที่หายนะที่เขาเป็นคนปลดปล่อยออกมาจะทำลายทุกสิ่ง', '2026-01-01', 7.50, 'https://image.tmdb.org/t/p/w342/1ATXKrIPJyKNwnJ6lcG088Sa6zi.jpg', 912.0000),
        (1323244, 'Rage of Stars', NULL, 'Rage of Stars', 'en', NULL, 'A story about a woman from the International Special Forces Unit, who has a premonition about the impending end of humanity.', '2026-01-01', 6.60, 'https://image.tmdb.org/t/p/w342/oLld47ZT1I3iecM3OWhIphohQUJ.jpg', 911.0000),
        (1386315, 'The Runner', 'เดอะรันเนอร์', 'The Runner', 'en', NULL, 'ในภาพยนตร์ระทึกขวัญจิตวิทยาเรื่องเดอะรันเนอร์ ไมอา มาร์เทนทนายความผู้ปราดเปรื่องแห่งลอนดอนต้องเจอเรื่องช็อกขณะวิ่งจ๊อกกิ้งตอนเช้า เมื่อสายปริศนาโทรมาบอกว่าลูกชายของเธอถูกลักพาตัวไป หากต้องการได้ลูกคืน เธอต้องวิ่งต่อไป ทำตามคำสั่งสุดโหดทุกข้อ และห้ามไว้ใจใคร วินาทีต่อจากนี้คือบททดสอบว่าคนเป็นแม่จะยอมทำเพื่อลูกได้มากแค่ไหน', '2026-01-01', 6.80, 'https://image.tmdb.org/t/p/w342/uxCaBoYXsDC4A0SqTm3SISj0OwK.jpg', 910.0000),
        (276488, 'Let Us Prey', NULL, 'Let Us Prey', 'en', NULL, 'Rachel, a rookie cop, is about to begin her first night shift in a neglected police station in a Scottish, backwater town. The kind of place where the tide has gone out and stranded a motley bunch of the aimless, the forgotten, the bitter-and-twisted who all think that, really, they deserve to be somewhere else. They all think they''re there by accident and that, with a little luck, life is going to get better. Wrong, on both counts. Six is about to arrive - and All Hell Will Break Loose!', '2014-01-01', 5.70, 'https://image.tmdb.org/t/p/w342/7X5VhHwDaSLkrDoifRbfvGZJxFP.jpg', 909.0000),
        (1130948, 'Rosebush Pruning', NULL, 'Rosebush Pruning', 'en', NULL, 'When an American heir living in a luxurious Spanish villa decides to move in with his girlfriend, his departure triggers a family collapse as his brother uncovers the truth behind their mother''s tragic death.', '2026-01-01', 6.10, 'https://image.tmdb.org/t/p/w342/rsHEVjzxU8cxz1sm3vboj99daNv.jpg', 908.0000),
        (1185806, 'PAW Patrol: The Dino Movie', 'ขบวนการเจ้าตูบสี่ขา เดอะ ไดโน มูฟวี่', 'PAW Patrol: The Dino Movie', 'en', NULL, 'ขบวนการเจ้าตูบสี่ขา มาเยือนเกาะไดโนเสาร์ลึกลับแห่งหนึ่งหลังจากเผชิญหน้ากับพายุ ที่ซึ่งพวกเขาได้พบกับ เร็กซ์ สุนัขผู้โดดเดี่ยว และเมื่อการขุดแร่โดยไม่ยั้งคิดของ ฮัมดิงเกอร์ ได้กระตุ้นการปะทุของภูเขาไฟ ขบวนการเจ้าตูบสี่ขาจีงจำเป็นต้องเผชิญภารกิจช่วยเหลือครั้งใหญ่ที่ช่วยเพื่อรักษาเกาะแห่งนี้เอาไว้', '2026-01-01', 8.20, 'https://image.tmdb.org/t/p/w342/qnin56Syy5rbG7KCaxWY7SPuy6p.jpg', 907.0000),
        (1084242, 'Zootopia 2', 'นครสัตว์มหาสนุก 2', 'Zootopia 2', 'en', NULL, 'จูดี้ ฮอปส์ ตำรวจกระต่ายกระต่ายผู้กล้าหาญ กลับมาร่วมทีมกับ นิค เพื่อนสุนัขจิ้กจอกของเขาอีกครั้งเพื่อไขปริศนาคดีใหม่ ซึ่งเป็นคดีที่อันตรายและซับซ้อนที่สุดเท่าที่ทั้งสองเคยพบเจอมา', '2025-01-01', 7.70, 'https://image.tmdb.org/t/p/w342/oJ7g2CifqpStmoYQyaLQgEU32qO.jpg', 906.0000),
        (1621552, 'Facing El Chapo', 'เผชิญหน้าเอล ชาโป', 'Facing El Chapo', 'en', NULL, 'เม็กซิโกปี 2016 เมื่อปฏิบัติการของนาวิกโยธินเกิดผิดแผน ตำรวจสองนายจึงต้องเผชิญหน้ากับเป้าหมายที่ตนตามล่า ซึ่งเป็นหนึ่งในมือสังหารของแก๊งค้ายาที่อันตรายที่สุดในโลก', '2026-01-01', 8.80, 'https://image.tmdb.org/t/p/w342/alpf5v4UqSFawPmG9RX03Or4BDk.jpg', 905.0000),
        (1284465, 'The Death of Robin Hood', 'บันทึกสุดท้ายของจอมโจร', 'The Death of Robin Hood', 'en', NULL, 'ในขณะที่กำลังต่อสู้กับอดีตของตัวเอง หลังจากใช้ชีวิตที่เต็มไปด้วยอาชญากรรมและการเข่นฆ่า โรบินฮู้ด ต้องพบกับอาการบาดเจ็บถึงตายหลังจากการต่อสู้ที่เขาคิดว่าคงจะเป็นครั้งสุดท้ายของตัวเอง และในความดูแลของหญิงลึกลับ เขาก็ถูกเสนอให้พบกับโอกาสที่จะไถ่บาป', '2026-01-01', 6.60, 'https://image.tmdb.org/t/p/w342/13MmRwmG5NmaMfU8qNrtgGXisiD.jpg', 904.0000),
        (1156869, 'Blaze of Love', NULL, 'Blaze of Love', 'en', NULL, 'Hong Kong movie', '1994-01-01', 0.00, 'https://image.tmdb.org/t/p/w342/cSOW4av17KfO9K2CRqKCjMbeoMw.jpg', 903.0000),
        (980431, 'Avatar Aang: The Last Airbender', NULL, 'Avatar Aang: The Last Airbender', 'en', NULL, 'Avatar Aang, the world''s last Airbender, learns of an ancient power that could save his culture from extinction. With the help of his friends, he embarks on a global quest to find it before it falls into the wrong hands and threatens to upend the peace they sacrificed everything to achieve.', '2026-01-01', 9.10, 'https://image.tmdb.org/t/p/w342/3sgnSfNT27Bx5O5ukr7B26mhEQq.jpg', 902.0000),
        (1419406, 'The Shadow''s Edge', 'แผนระห่ำ ใหญ่ฟัดเดือด', 'The Shadow''s Edge', 'en', NULL, 'ตำรวจมาเก๊าได้ดึงเอาตัวตำรวจผู้เชี่ยวชาญในการตามรอยกลับมาจากการเกษียณ เพื่อที่จะให้เขาช่วยเหลือในการจับกุมกลุ่มโจรมืออาชีพ', '2025-01-01', 8.30, 'https://image.tmdb.org/t/p/w342/cHKo3m8N1fwvEy2ZEr0xGmmMODV.jpg', 901.0000)
